import { performanceQuestions } from './questions-performance.js';

// English text is authored in the same pre-rotation order as the Chinese source.
// Apply the source's stable rotation so saved answer indexes work in either language.
const originals = new Map(performanceQuestions.map(question => [question.id, question]));
function en(number, topic, stem, options, explanation, optionExplanations, takeaway) {
  const original = originals.get(`perf-${String(number).padStart(3, '0')}`);
  const offset = (number * 7) % options.length;
  const rotate = values => values.slice(offset).concat(values.slice(0, offset));
  return { ...original, topic, stem, options: rotate(options), explanation, optionExplanations: rotate(optionExplanations), takeaway };
}

